patch_rows as (
  select *
  from patch_payload,
  jsonb_to_recordset(patch_payload.data) as row(
    external_id text,
    format text,
    stem text,
    options_json jsonb,
    correct_answer_json jsonb,
    markscheme_points_json jsonb,
    explanation text,
    max_marks integer,
    content_blocks_json jsonb,
    response_schema_json jsonb,
    autograde_rules_json jsonb,
    tags_json jsonb
  )
)
update public.questions q
set format = p.format::public.question_format,
    stem = p.stem,
    options_json = p.options_json,
    correct_answer_json = p.correct_answer_json,
    markscheme_points_json = p.markscheme_points_json,
    explanation = p.explanation,
    max_marks = greatest(1, least(20, coalesce(p.max_marks, 1)))::smallint,
    content_blocks_json = p.content_blocks_json,
    response_schema_json = p.response_schema_json,
    autograde_rules_json = p.autograde_rules_json,
    tags_json = p.tags_json,
    teacher_notes = concat_ws(' | ', nullif(q.teacher_notes, ''), 'Content accuracy hotfix 2026-05-04: checked exact-marked answers and improved objective reliability or aliases.')
from patch_rows p
where q.external_id = p.external_id;

update public.session_questions sq
set question_snapshot_json = public.build_runtime_question_payload(sq.question_id, sq.id)
from public.sessions s, public.questions q
where s.id = sq.session_id
  and q.id = sq.question_id
  and s.completed_at is null
  and q.external_id = any (array['software.past_paper.topics_01_02.q017', 'database-applications.past_paper.topics_03_04.q003', 'database-applications.past_paper.topics_03_04.q006', 'computer-hardware.past_paper.topics_05_06.q007', 'computer-hardware.past_paper.topics_05_06.q010', 'computer-hardware.past_paper.topics_05_06.q024', 'computer-hardware.past_paper.topics_05_06.q040', 'network-technologies.past_paper.topics_05_06.q006', 'network-technologies.past_paper.topics_05_06.q022', 'network-technologies.past_paper.topics_05_06.q028', 'network-technologies.past_paper.topics_05_06.q031', 'network-technologies.past_paper.topics_05_06.q044', 'changes-in-employment-opportunities-skills-requirements-and-work-practices.past_paper.topics_10_11_12.q004', 'changes-in-employment-opportunities-skills-requirements-and-work-practices.past_paper.topics_10_11_12.q005', 'changes-in-employment-opportunities-skills-requirements-and-work-practices.past_paper.topics_10_11_12.q006', 'digital-applications.past_paper.topics_10_11_12.q007', 'digital-applications.past_paper.topics_10_11_12.q011', 'digital-applications.past_paper.topics_10_11_12.q012', 'digital-data.practice_bank.topic_01_digital_data.q021', 'digital-data.practice_bank.topic_01_digital_data.q065', 'digital-data.practice_bank.topic_01_digital_data.q119', 'software.practice_bank.topic_02_03_software_database.q032', 'software.practice_bank.topic_02_03_software_database.q033', 'database-applications.practice_bank.topic_02_03_software_database.q058', 'computer-hardware.practice_bank.topic_05_06_hardware_networks.q027', 'network-technologies.practice_bank.topic_05_06_hardware_networks.q029', 'cyberspace-network-security-and-data-transfer.practice_bank.topic_07_08_cyberspace_cloud.q037', 'cloud-technology.practice_bank.topic_07_08_cyberspace_cloud.q014', 'ethical-legal-and-environmental-impact.practice_bank.topic_09_12_wider_impact.q017', 'changes-in-employment-opportunities-skills-requirements-and-work-practices.practice_bank.topic_09_12_wider_impact.q016']);

do $$
declare
  cache_memory_alone_ok boolean;
  cache_alias_ok boolean;
  tcpip_ok boolean;
  color_depth_ok boolean;
begin
  select public.answer_text_matches('memory', autograde_rules_json -> 'accepted', 'phrase', 'exact') into cache_memory_alone_ok
  from public.questions
  where external_id = 'software.practice_bank.topic_02_03_software_database.q033';

  if coalesce(cache_memory_alone_ok, false) then
    raise exception 'Key-term hotfix failed: plain memory is still accepted for cache question';
  end if;

  select public.answer_text_matches('cache memory', autograde_rules_json -> 'accepted', 'phrase', 'exact') into cache_alias_ok
  from public.questions
  where external_id = 'software.practice_bank.topic_02_03_software_database.q033';

  if not coalesce(cache_alias_ok, false) then
    raise exception 'Key-term hotfix failed: cache memory is not accepted';
  end if;

  select public.answer_text_matches('TCPIP', autograde_rules_json -> 'accepted', 'phrase', 'exact') into tcpip_ok
  from public.questions
  where external_id = 'cyberspace-network-security-and-data-transfer.practice_bank.topic_07_08_cyberspace_cloud.q037';

  if not coalesce(tcpip_ok, false) then
    raise exception 'Key-term hotfix failed: TCPIP alias is not accepted';
  end if;

  select public.answer_text_matches('color depth', autograde_rules_json -> 'accepted', 'phrase', 'exact') into color_depth_ok
  from public.questions
  where external_id = 'digital-data.practice_bank.topic_01_digital_data.q119';

  if not coalesce(color_depth_ok, false) then
    raise exception 'Key-term hotfix failed: color depth alias is not accepted';
  end if;
end $$;

